      if (!Number.isFinite(ts)) return { status: 'UNKNOWN', posted_at: null, timestamp: null, valid: false };
      if (elapsed <= 30 * DAY_MS) return { status: 'CURRENT', posted_at: null, timestamp: ts, valid: true };
