    if (m) { const d = mkAbs(parseInt(m[3], 10), parseInt(m[2], 10), parseInt(m[1], 10)); return d ? classifyAbs(d) : { status: 'UNKNOWN', posted_at: null, timestamp: null, valid: false }; }
    m = s.match(/^([0-9]{2})\/([0-9]{2})\/([0-9]{4})$/);
